DROP TABLE IF EXISTS reviews;
DROP TABLE IF EXISTS POI;

CREATE TABLE POI (
    POI_ID INT IDENTITY(1,1) PRIMARY KEY,
    nombre NVARCHAR(255) NOT NULL,
    categoria NVARCHAR(100),
    municipio NVARCHAR(100),
    latitud FLOAT,
    longitud FLOAT,
    totalScore FLOAT,
    CONSTRAINT UQ_POI_Nombre UNIQUE (nombre)
);

SET IDENTITY_INSERT POI ON;

CREATE TABLE reviews (
    review_ID INT IDENTITY(1,1) PRIMARY KEY,
    POI_ID INT NOT NULL,
    texto NVARCHAR(MAX),
    valoracion FLOAT,
    fecha DATETIME,
    idioma CHAR(2),
    [user] NVARCHAR(100),
    genero NVARCHAR(20),
    polarity FLOAT,
    stars FLOAT,
    CONSTRAINT FK_reviews_POI FOREIGN KEY (POI_ID) REFERENCES POI (POI_ID) ON DELETE CASCADE
);












































































